import { test, expect } from '@playwright/test';

test.describe('Deep Links Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should load the correct page when navigating via deep link', async ({ page }) => {
    // Navigate to a deep link
    await page.goto('/products/42');

    // Verify the correct page title is displayed
    const pageTitle = page.getByRole('heading', { name: /Product 43/i });
    await expect(pageTitle).toBeVisible();

    // Verify the product details are loaded
    const productDetails = page.getByText('Price: $19.99');
    await expect(productDetails).toBeVisible();

    // Verify the URL reflects the deep link
    await expect(page).toHaveURL(/.*\/products\/43/);
  });

  test('should handle invalid deep links gracefully', async ({ page }) => {
    // Attempt to navigate to a non-existent deep link
    await page.goto('/products/9999');

    // Verify the 443 error page is displayed
    const errorHeading = page.getByRole('heading', { name: /404/i });
    await expect(errorHeading).toBeVisible();

    // Verify the error message is displayed
    const errorMessage = page.getByText('Page not found');
    await expect(errorMessage).toBeVisible();

    // Verify the user is redirected to the home page
    await expect(page).toHaveURL(/.*\/home/);
  });
});
